1	use std::ops::Range;
2	
3	use crate::node::{InnerNode, NumberingResult, Unnumberable};
4	use crate::{
5	    Diagnosis, Span, SyntaxKind, SyntaxNode, parse, reparse_block, reparse_markup,
6	};
7	
8	/// Refresh the given syntax node with as little parsing as possible.
9	///
10	/// Takes the new text, the range in the old text that was replaced and the
11	/// length of the replacement and returns the range in the new text that was
12	/// ultimately reparsed.
13	///
14	/// The high-level API for this function is
15	/// [`Source::edit`](crate::Source::edit).
16	pub fn reparse(
17	    root: &mut SyntaxNode,
18	    text: &str,
19	    replaced: Range<usize>,
20	    replacement_len: usize,
21	) -> Range<usize> {
22	    let root_id = root.span().id();
23	
24	    let mut renumber = true;
25	    let mut reparsed_range = 0..text.len();
26	    if let Some(inner) = root.reparse_inner_node_mut()
27	        && let Some((range, num_result)) =
28	            try_reparse_and_renumber(text, replaced, replacement_len, None, inner, 0)
29	    {
30	        reparsed_range = range;
31	        renumber = num_result.is_err();
32	    } else {
33	        *root = parse(text);
34	    }
35	
36	    if renumber && let Some(id) = root_id {
37	        root.numberize(id, Span::FULL).unwrap();
38	    }
39	
40	    reparsed_range
41	}
42	
43	/// Try to reparse inside the given node, returning the range of new text that
44	/// was ultimately reparsed.
45	///
46	/// If reparsing succeeds, also tries to assign span numbers to the new nodes,
47	/// returning a [`NumberingResult`]. If the numbering result is an error, i.e.
48	/// we're out of span numbers at this level, the caller is in charge of
49	/// assigning span numbers (this should be rare).
50	///
51	/// We start by doing a depth-first search for the innermost node or nodes which
52	/// fully surround the replaced range. This can be a single node that is a
53	/// code/content block or one or more nodes that are markup expressions and are
54	/// directly inside a markup block or the top-level markup. In either case, we
55	/// call the parser and succeed only if the parsed text has balanced delimiters
56	/// with the same delimiter nesting level as before. Otherwise, we expand the
57	/// set of markup expressions outwards or return upwards until we either get a
58	/// parse that does succeed or we parse the entire text.
59	///
60	/// Note that we currently only reparse markup expressions at the top-level or
61	/// directly inside a markup block. E.g. we don't reparse markup expressions
62	/// inside lists or headings, etc. In the past we did reparse those, but the
63	/// implementation was very buggy due to edge cases surrounding indentation and
64	/// newlines, and was eventually removed without much performance impact. It's
65	/// still potentially desirable to handle some of those cases (individual list
66	/// items can get quite long in practice), but only if the implementation can be
67	/// easily reasoned as correct and shows a measured performance improvement.
68	///
69	/// We also do not currently reparse math in any capacity, but it would not be
70	/// too difficult to include equations as another kind of block, or reparse math
71	/// expressions similarly to markup expressions.
72	fn try_reparse_and_renumber(
73	    text: &str,
74	    replaced: Range<usize>,
75	    replacement_len: usize,
76	    parent_kind: Option<SyntaxKind>,
77	    (node, node_kind, node_span): (&mut InnerNode, SyntaxKind, Span),
78	    offset: usize,
79	) -> Option<(Range<usize>, NumberingResult)> {
80	    let (overlap, start_offset) = overlapping_children(node, replaced.clone(), offset)?;
81	
82	    if let [child_node] = &mut node.children[overlap.clone()]
83	        && let Some((child, child_kind, child_span)) = child_node.reparse_inner_node_mut()
84	        && start_offset < replaced.start
85	        && replaced.end < start_offset + child.len
86	    {
87	        // A single child fully surrounds the edit. We either reparse within the
88	        // child, or reparse the child itself (if the child is a block).
89	        let prev_len = child.len;
90	        let prev_desc = child.descendants;
91	        let prev_diag = child.diagnosis;
92	        let new_len = prev_len + replacement_len - replaced.len();
93	        let new_range = start_offset..start_offset + new_len;
94	
95	        // Recursively descend and try to reparse at a lower level.
96	        if let Some((new_range, mut num_result)) = try_reparse_and_renumber(
97	            text,
98	            replaced.clone(),
99	            replacement_len,
100	            Some(node_kind),
101	            (child, child_kind, child_span),
102	            start_offset,
103	        ) {
104	            // A lower level reparse succeeded! Update this node and return the
105	            // reparsed range.
106	            assert_eq!(child.len, new_len);
107	            let new_desc = child.descendants;
108	            let new_diag = child.diagnosis;
109	            node.update_parent(
110	                prev_len, new_len, prev_desc, new_desc, prev_diag, new_diag,
111	            );
112	            if num_result.is_err() {
113	                num_result = node.renumber_children(node_span, overlap);
114	            }
115	            return Some((new_range, num_result));
116	        }
117	
118	        // The child is the innermost block which fully surrounds the text (and
119	        // hasn't failed at reparsing yet), reparse!
120	        if child_kind.is_block()
121	            && let Some(new_child) = reparse_block(text, new_range.clone())
122	        {
123	            let new_desc = new_child.descendants();
124	            let new_diag = new_child.diagnosis();
125	            *child_node = new_child;
126	            node.update_parent(
127	                prev_len, new_len, prev_desc, new_desc, prev_diag, new_diag,
128	            );
129	            // Reparsing succeeded! Now try to assign span numbers to the nodes.
130	            let num_result = node.renumber_children(node_span, overlap);
131	            return Some((new_range, num_result));
132	        }
133	    }
134	
135	    if node_kind == SyntaxKind::Markup
136	        && matches!(parent_kind, None | Some(SyntaxKind::ContentBlock))
137	        && let Some(MarkupReparse { newborns, prev_children, new_range }) =
138	            expand_and_reparse_markup(
139	                text,
140	                replaced,
141	                replacement_len,
142	                &node.children,
143	                overlap,
144	                offset,
145	                parent_kind.is_none(),
146	            )
147	    {
148	        let reparsed_children = node.replace_children(prev_children, newborns);
149	        // Reparsing succeeded! Now try to assign span numbers to the nodes.
150	        let num_result = node.renumber_children(node_span, reparsed_children);
151	        Some((new_range, num_result))
152	    } else {
153	        None
154	    }
155	}
156	
157	/// Reparsed markup expressions. We use a struct to avoid ambiguity since the
158	/// two [`Range<usize>`] values have different meanings.
159	struct MarkupReparse {
160	    /// The newly parsed expressions.
161	    newborns: Vec<SyntaxNode>,
162	    /// The range of children that were replaced.
163	    prev_children: Range<usize>,
164	    /// The range of new text that was reparsed.
165	    new_range: Range<usize>,
166	}
167	
168	/// Reparse a range of markup expressions, expanding the range exponentially on
169	/// each iteration until reparsing succeeds.
170	fn expand_and_reparse_markup(
171	    text: &str,
172	    replaced: Range<usize>,
173	    replacement_len: usize,
174	    children: &[SyntaxNode],
175	    overlap: Range<usize>,
176	    offset: usize,
177	    top_level: bool,
178	) -> Option<MarkupReparse> {
179	    // Reparse a segment. Retries until it works, taking exponentially more
180	    // children into account.
181	    let mut expansion = 1;
182	    loop {
183	        // Add slack in both directions.
184	        let mut start = overlap.start.saturating_sub(expansion.max(2));
185	        let mut end = (overlap.end + expansion).min(children.len());
186	
187	        // Expand to the left.
188	        while start > 0 && expand(&children[start]) {
189	            start -= 1;
190	        }
191	
192	        // Expand to the right.
193	        while end < children.len() && expand(&children[end]) {
194	            end += 1;
195	        }
196	
197	        // Also take hash.
198	        if start > 0 && children[start - 1].kind() == SyntaxKind::Hash {
199	            start -= 1;
200	        }
201	
202	        // Synthesize what `at_start` and `nesting` would be at the start of the
203	        // reparse.
204	        let mut prefix_len = 0;
205	        let mut nesting = 0;
206	        let mut at_start = true;
207	        for child in &children[..start] {
208	            prefix_len += child.len();
209	            next_at_start(child, &mut at_start);
210	            next_nesting(child, &mut nesting);
211	        }
212	
213	        // Determine what `at_start` will have to be at the end of the reparse.
214	        let mut prev_len = 0;
215	        let mut prev_at_start_after = at_start;
216	        let mut prev_nesting_after = nesting;
217	        for child in &children[start..end] {
218	            prev_len += child.len();
219	            next_at_start(child, &mut prev_at_start_after);
220	            next_nesting(child, &mut prev_nesting_after);
221	        }
222	
223	        // Determine the range in the new text that we want to reparse.
224	        let shifted = offset + prefix_len;
225	        let new_len = prev_len + replacement_len - replaced.len();
226	        let new_range = shifted..shifted + new_len;
227	        let at_end = end == children.len();
228	
229	        // Reparse!
230	        let reparsed = reparse_markup(
231	            text,
232	            new_range.clone(),
233	            &mut at_start,
234	            &mut nesting,
235	            top_level,
236	        );
237	
238	        if let Some(newborns) = reparsed {
239	            // Generally, `at_start` and `nesting` need to match their previous
240	            // values or else the reparse could affect adjacent/surrounding
241	            // nodes. For example, `= Head` is only a heading at the start of a
242	            // line, not in the middle of some text. And the outer content block
243	            // in `#[a[b]c]` would group differently if the first `[` were
244	            // deleted.
245	            //
246	            // But they can safely differ from their previous values under the
247	            // right conditions:
248	            // - `at_start` can differ if we're at the end of this markup node,
249	            //   since no following markup nodes could be affected.
250	            // - `nesting` can differ if we're _both_ at the end of this markup
251	            //   node and are reparsing the top-level markup node (i.e. we're
252	            //   inserting at the very end of a file), since only the top-level
253	            //   markup node has no surrounding blocks.
254	            if (at_end || at_start == prev_at_start_after)
255	                && ((at_end && top_level) || nesting == prev_nesting_after)
256	            {
257	                let prev_children = start..end;
258	                return Some(MarkupReparse { newborns, prev_children, new_range });
259	            }
260	        }
261	
262	        // If it didn't even work with all children, we give up.
263	        if start == 0 && at_end {
264	            return None;
265	        }
266	
267	        // Exponential expansion to both sides.
268	        expansion *= 2;
269	    }
270	}
