272	/// The indices and start offset of the children which overlap a replaced range.
273	/// Returns `None` if the children don't fully cover the range. Will never
274	/// return an empty range if it returns `Some`.
275	///
276	/// Note that the returned `Range<usize>` is the range of children in the
277	/// parent, but the returned `usize` is a byte offset in the source text.
278	fn overlapping_children(
279	    node: &InnerNode,
280	    range: Range<usize>,
281	    mut offset: usize,
282	) -> Option<(Range<usize>, usize)> {
283	    if offset > range.start || range.end > offset + node.len {
284	        // No set of children will fully cover the range, no need to search.
285	        return None;
286	    }
287	    let mut index = 0;
288	    let mut start = 0;
289	    let mut start_offset = offset;
290	    for child in &node.children {
291	        if offset < range.start {
292	            start = index;
293	            start_offset = offset;
294	        }
295	        offset += child.len();
296	        index += 1;
297	        if range.end < offset {
298	            break;
299	        }
300	    }
301	    debug_assert!(start_offset <= range.start);
302	    debug_assert!(range.end <= offset);
303	    Some((start..index, start_offset))
304	}
305	
306	/// Whether the selection should be expanded beyond a node of this kind.
307	fn expand(node: &SyntaxNode) -> bool {
308	    let kind = node.kind();
309	    kind.is_trivia()
310	        || kind.is_error()
311	        || kind == SyntaxKind::Semicolon
312	        || node.leaf_text() == "/"
313	        || node.leaf_text() == ":"
314	}
315	
316	/// Whether `at_start` would still be true after this node given the
317	/// previous value of the property.
318	fn next_at_start(node: &SyntaxNode, at_start: &mut bool) {
319	    let kind = node.kind();
320	    if kind.is_trivia() {
321	        *at_start |= matches!(kind, SyntaxKind::Parbreak | SyntaxKind::SpaceWithNewline);
322	    } else {
323	        *at_start = false;
324	    }
325	}
326	
327	/// Update `nesting` based on the node.
328	fn next_nesting(node: &SyntaxNode, nesting: &mut usize) {
329	    if node.kind() == SyntaxKind::Text {
330	        match node.leaf_text().as_str() {
331	            "[" => *nesting += 1,
332	            "]" if *nesting > 0 => *nesting -= 1,
333	            _ => {}
334	        }
335	    }
336	}
