338	impl InnerNode {
339	    /// Update this node after one or more of its children were replaced or
340	    /// updated. The new children must already be in `self.children`.
341	    ///
342	    /// `prev_*` variables should come from the previous range of children.
343	    /// `new_*` are for the new range of children.
344	    fn update_parent(
345	        &mut self,
346	        prev_len: usize,
347	        new_len: usize,
348	        prev_descendants: usize,
349	        new_descendants: usize,
350	        prev_diagnosis: Diagnosis,
351	        new_diagnosis: Diagnosis,
352	    ) {
353	        // Length and descendants are numerical, can update with algebra.
354	        // Subtract the previous values first to avoid potential overflow.
355	        self.len = (self.len - prev_len) + new_len;
356	        self.descendants = (self.descendants - prev_descendants) + new_descendants;
357	
358	        // Our diagnosis is the `OR` of all our children's diagnoses.
359	        if !self.diagnosis.either() || new_diagnosis.both() {
360	            // We can avoid iterating our children if our previous overall state
361	            // had no errors/warnings, or if the new children have both.
362	            self.diagnosis = new_diagnosis;
363	        } else if prev_diagnosis != new_diagnosis {
364	            // Otherwise, we recompute using all the children since we don't
365	            // know if there were multiple children with errors or warnings.
366	            self.diagnosis = Diagnosis::any(&self.children);
367	        }
368	    }
369	
370	    /// Replace a range of children and calls [`Self::update_parent`].
371	    /// [`Self::renumber_children`] should be called immediately after this.
372	    ///
373	    /// To increase the stability of span numbers, this does not replace nodes
374	    /// at the front/back that are equal to the previous nodes. Returns the
375	    /// final indices of the inserted nodes.
376	    pub fn replace_children(
377	        &mut self,
378	        mut range: Range<usize>,
379	        mut replacement: Vec<SyntaxNode>,
380	    ) -> Range<usize> {
381	        let mut replacement_range = 0..replacement.len();
382	
383	        // Trim off common prefix.
384	        while range.start < range.end
385	            && replacement_range.start < replacement_range.end
386	            && self.children[range.start]
387	                .spanless_eq(&replacement[replacement_range.start])
388	        {
389	            range.start += 1;
390	            replacement_range.start += 1;
391	        }
392	
393	        // Trim off common suffix.
394	        while range.start < range.end
395	            && replacement_range.start < replacement_range.end
396	            && self.children[range.end - 1]
397	                .spanless_eq(&replacement[replacement_range.end - 1])
398	        {
399	            range.end -= 1;
400	            replacement_range.end -= 1;
401	        }
402	
403	        // Compute child information for the `update_parent` call.
404	        let new = &replacement[replacement_range.clone()];
405	        let new_len = new.iter().map(SyntaxNode::len).sum::<usize>();
406	        let new_desc = new.iter().map(SyntaxNode::descendants).sum::<usize>();
407	        let new_diag = Diagnosis::any(new);
408	
409	        let prev = &self.children[range.clone()];
410	        let prev_len = prev.iter().map(SyntaxNode::len).sum::<usize>();
411	        let prev_desc = prev.iter().map(SyntaxNode::descendants).sum::<usize>();
412	        let prev_diag = Diagnosis::any(prev);
413	
414	        let replaced_range = range.start..range.start + new.len();
415	
416	        self.children.splice(range, replacement.drain(replacement_range));
417	        self.update_parent(prev_len, new_len, prev_desc, new_desc, prev_diag, new_diag);
418	
419	        replaced_range
420	    }
421	
422	    /// Try to assign span numbers to a range of children. If there are not
423	    /// enough numbers, retries taking exponentially more children into account.
424	    pub fn renumber_children(
425	        &mut self,
426	        span: Span,
427	        range: Range<usize>,
428	    ) -> NumberingResult {
429	        let Some(id) = span.id() else { return Err(Unnumberable) };
430	
431	        let mut left = 0;
432	        let mut right = 0;
433	        let max_left = range.start;
434	        let max_right = self.children.len() - range.end;
435	        loop {
436	            let renumber = range.start - left..range.end + right;
437	
438	            // The minimum assignable number is either
439	            // - the upper bound of the node right before the to-be-renumbered
440	            //   children,
441	            // - or this inner node's span number plus one if renumbering starts
442	            //   at the first child.
443	            let start_number = renumber
444	                .start
445	                .checked_sub(1)
446	                .and_then(|i| self.children.get(i))
447	                .map_or(span.number() + 1, |child| child.upper());
448	
449	            // The upper bound for renumbering is either
450	            // - the span number of the first child after the to-be-renumbered
451	            //   children,
452	            // - or this node's upper bound if renumbering ends behind the last
453	            //   child.
454	            let end_number = self
455	                .children
456	                .get(renumber.end)
457	                .map_or(self.upper, |next| next.span().number());
458	
459	            // Try to renumber.
460	            let within = start_number..end_number;
461	            if self.numberize(None, id, Some(renumber), within).is_ok() {
462	                return Ok(());
463	            }
464	
465	            // If it didn't even work with all children, we give up.
466	            if left == max_left && right == max_right {
467	                return Err(Unnumberable);
468	            }
469	
470	            // Exponential expansion to both sides.
471	            left = (left + 1).next_power_of_two().min(max_left);
472	            right = (right + 1).next_power_of_two().min(max_right);
473	        }
474	    }
475	}
