484	    /// How to replace text in the test string.
485	    enum Edit {
486	        /// Insert at the end.
487	        End,
488	        /// Insert at an index.
489	        At(usize),
490	        /// Replace the given range.
491	        Range(Range<usize>),
492	        /// Replace the first match in the original.
493	        Match(&'static str),
494	        /// Insert at the index after the first match of this string.
