498	    impl Edit {
499	        #[track_caller]
500	        fn into_range(self, text: &str) -> Range<usize> {
501	            match self {
502	                Self::End => text.len()..text.len(),
503	                Self::At(index) => {
504	                    assert!(text.len() >= index, "index is out of bounds");
505	                    index..index
506	                }
507	                Self::Range(range) => {
508	                    assert!(text.len() >= range.end, "range is out of bounds");
509	                    range
510	                }
511	                Self::Match(pat) => {
512	                    let start = text.find(pat).expect("pattern must exist in original");
513	                    start..start + pat.len()
514	                }
515	                Self::After(pat) => {
516	                    let start = text.find(pat).expect("pattern must exist in original");
517	                    let end = start + pat.len();
518	                    end..end
519	                }
520	            }
521	        }
522	    }
