742	            // Leave the number of nodes the same:
743	            test(&text, Edit::Match("A~B"), "A~B", Reparse::Incr(" A~B "));
744	            test(&text, Edit::Match("A~B"), "3~B", Reparse::Incr(" 3~B "));
745	            test(&text, Edit::After("A"), "3", Reparse::Incr(" A3~B "));
746	
747	            // Increase the number of nodes:
748	            test(&text, Edit::After("A"), "~4", Reparse::Incr(" A~4~B "));
749	            test(&text, Edit::At(2 * n + 3), "5~", Reparse::Incr(" A~5~B "));
750	        }
751	    }
752	
753	    /// Don't incrementally reparse ranges inside a syntax warning.
754	    #[test]
755	    fn test_reparse_within_warnings() {
756	        // We build a custom tree with a warning since we don't currently
757	        // produce any syntax warnings that would trigger this bug.
758	        let text = "#[nor~mal] #[warn~ing]".to_string();
759	        let mut root = parse(&text);
760	
761	        let root_inner = root.reparse_inner_node_mut().unwrap().0;
762	        let second_block = &mut root_inner.children[4];
763	        assert_eq!(second_block.full_text(), "[warn~ing]");
764	        // Note how the warning message can include text from within the node
765	        // arbitrarily. This is the primary reason reparsing within warnings is
766	        // unsound: there's no way to know how to update the message/hints!
767	        second_block.warn_at(5..6, "tilde between `warn` and `ing`: `~`");
768	        // We have to update the parent's diagnosis due to the new warning.
769	        let warning_diagnosis = Diagnosis { warnings: true, errors: false };
770	        // `{new,prev}_{len,desc}` are 0 since only their difference matters.
771	        root_inner.update_parent(0, 0, 0, 0, Diagnosis::default(), warning_diagnosis);
772	        assert!(root.diagnosis().warnings);
773	
774	        // Assign initial span numbers so we can properly reparse.
775	        let id = FileId::new_for_test("reparse_within_warnings");
776	        root.numberize(id, Span::FULL).unwrap();
777	        let mut source = Source::with_root(id, text, root);
778	
779	        // First we edit and reparse `nor~mal` into `normal`. The reparsed range
780	        // should stay within the content block.
781	        let replaced = Edit::Match("r~m").into_range(source.text());
782	        let replace_with = "rm";
783	        let reparsed = source.edit(replaced, replace_with);
784	        assert_eq!(&source.text()[reparsed], "normal");
785	        // Reparsing `normal` should not affect the warning:
786	        assert!(source.root().diagnosis().warnings);
787	
788	        // Then we edit and reparse `warn~ing` into `warning`. Even though the
789	        // edit is fully inside the warned content block, the reparsed range
790	        // should expand to the outer code block since we can't soundly reparse
791	        // within warnings.
792	        let replaced = Edit::Match("n~i").into_range(source.text());
793	        let replace_with = "ni";
794	        let reparsed = source.edit(replaced, replace_with);
795	        assert_eq!(&source.text()[reparsed], "#[normal] #[warning]");
796	        assert!(!source.root().diagnosis().warnings);
797	    }
798	}
