602	    /// Access an inner node mutably for incremental reparsing. Also returns the
603	    /// node's span and syntax kind since those are needed.
604	    ///
605	    /// Unlike [`Node::inner_mut`], this does not descend past wrapped warnings
606	    /// since reparsing under syntax warnings cannot be made sound. A warning's
607	    /// message, hints, or sub-ranges could target or include subsets of the
608	    /// replaced text, and trying to match and update those subsets correctly is
609	    /// not feasible in the general case.
610	    ///
611	    /// Luckily, avoiding reparsing under syntax warnings is unlikely to have a
612	    /// performance impact in real documents.
613	    pub(super) fn reparse_inner_node_mut(
614	        &mut self,
615	    ) -> Option<(&mut InnerNode, SyntaxKind, Span)> {
616	        match &mut self.data {
617	            Node::Inner(inner, kind) => Some((Arc::make_mut(inner), *kind, self.span)),
618	            _ => None,
619	        }
620	    }
621	}
