832	    /// Write with debug formatting using the node's overall span.
833	    ///
834	    /// See [`WarningWrapper::debug_fmt_span`] for more explanation.
835	    fn debug_fmt_span(&self, f: &mut Formatter, span: Span) -> fmt::Result {
836	        if self.text.is_empty() && self.hints.is_empty() {
837	            write!(f, "Error: {:?}", self.message)
838	        } else {
839	            let mut out = f.debug_struct("Error:");
840	            out.field("text", &self.text);
841	            out.field("message", &self.message);
842	            for (hint, sub_range) in &self.hints {
843	                let field = if let Some(sr) = sub_range {
844	                    if let SpanKind::Range { id: _, range } = span.get() {
845	                        let new_range = sr.to_absolute(range.start);
846	                        &format!("hint @mapped({new_range:?})")
847	                    } else {
848	                        let selected = &self.text[sr.to_relative()];
849	                        &format!("hint @text({selected:?})")
850	                    }
851	                } else {
852	                    "hint"
853	                };
854	                out.field(field, hint);
855	            }
856	            out.finish()
857	        }
858	    }
