232	impl<S: Hash> Hash for Lines<S> {
233	    fn hash<H: Hasher>(&self, state: &mut H) {
234	        self.0.text.hash(state);
235	    }
236	}
237	
238	impl<S: AsRef<str>> AsRef<str> for Lines<S> {
239	    fn as_ref(&self) -> &str {
240	        self.0.text.as_ref()
241	    }
242	}
